class Solution {
public:
    int numTilings(int n) {
        const int MOD = 1e9 + 7;
        if (n == 1) return 1;
        if (n == 2) return 2;

        long long f0 = 1, f1 = 1, f2 = 2;
        for (int i = 3; i <= n; i++) {
            long long f3 = (2 * f2 + f0) % MOD;
            f0 = f1;
            f1 = f2;
            f2 = f3;
        }
        return (int)f2;
    }
};
